package com.lootingbagtags;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/**
 * Matches item losses from a looting bag with item gains in an open bank.
 *
 * <p>Both maps must use canonical, unnoted item IDs. Call {@link #detect} once
 * after all container changes for a game tick have been applied, rather than
 * once for each individual container event. The order in which the bank and
 * bag events arrived then makes no difference.</p>
 *
 * <p>A null map means that the container is unknown, not empty. Unknown data,
 * opening the bank, and resetting the tracker establish a fresh baseline and
 * never report a deposit. No unmatched increases or decreases are carried
 * across observations: an unrelated later bank deposit must not get matched
 * against an old bag loss.</p>
 */
public final class BagDepositTracker
{
	private Map<Integer, Integer> previousBag;
	private Map<Integer, Integer> previousBank;
	private boolean bankWasOpen;

	/**
	 * Seeds the before-action snapshot without reporting any deposited items.
	 * This is useful when the bank first becomes available, before the player
	 * sends a deposit action. It is safe to call with unknown containers.
	 */
	public void prime(Map<Integer, Integer> bag, Map<Integer, Integer> bank, boolean bankOpen)
	{
		previousBag = snapshot(bag);
		previousBank = bankOpen ? snapshot(bank) : null;
		bankWasOpen = bankOpen;
	}

	/**
	 * Returns the item types observed moving from the bag into the bank.
	 * The result is immutable and is empty for an unconfirmed change.
	 */
	public Set<Integer> detect(Map<Integer, Integer> bag, Map<Integer, Integer> bank, boolean bankOpen)
	{
		Map<Integer, Integer> currentBag = snapshot(bag);
		Map<Integer, Integer> currentBank = bankOpen ? snapshot(bank) : null;
		Set<Integer> deposited = new TreeSet<>();

		if (bankOpen && bankWasOpen
			&& previousBag != null && currentBag != null
			&& previousBank != null && currentBank != null)
		{
			for (Map.Entry<Integer, Integer> entry : previousBag.entrySet())
			{
				int itemId = entry.getKey();
				long bagLoss = (long) entry.getValue() - currentBag.getOrDefault(itemId, 0);
				long bankGain = (long) currentBank.getOrDefault(itemId, 0)
					- previousBank.getOrDefault(itemId, 0);

				if (Math.min(bagLoss, bankGain) > 0)
				{
					deposited.add(itemId);
				}
			}
		}

		previousBag = currentBag;
		previousBank = currentBank;
		bankWasOpen = bankOpen;

		return deposited.isEmpty() ? Collections.emptySet() : Collections.unmodifiableSet(deposited);
	}

	/** Discards snapshots on logout, world hopping, or plugin shutdown. */
	public void reset()
	{
		previousBag = null;
		previousBank = null;
		bankWasOpen = false;
	}

	private static Map<Integer, Integer> snapshot(Map<Integer, Integer> items)
	{
		if (items == null)
		{
			return null;
		}

		Map<Integer, Integer> copy = new HashMap<>();
		for (Map.Entry<Integer, Integer> entry : items.entrySet())
		{
			if (entry.getKey() != null && entry.getKey() >= 0
				&& entry.getValue() != null && entry.getValue() > 0)
			{
				copy.put(entry.getKey(), entry.getValue());
			}
		}
		return copy;
	}
}

package com.lootingbagtags;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.TabManager;
import net.runelite.client.plugins.banktags.tabs.TagTab;
import net.runelite.client.util.Text;

/**
 * Maintains one ordinary Bank Tags tab. All methods must run on the client thread.
 */
@Singleton
public class LootingBagTagWriter
{
	private static final String CONFIG_GROUP = "lootingbagtags";
	private static final String MANAGED_TAG_KEY = "managedTag";
	private static final String DEFAULT_TAG_NAME = "looting bag deposits";

	private final ConfigManager configManager;
	private final PluginManager pluginManager;

	@Inject
	LootingBagTagWriter(ConfigManager configManager, PluginManager pluginManager)
	{
		this.configManager = configManager;
		this.pluginManager = pluginManager;
	}

	public String getTagName()
	{
		String name = configManager.getConfiguration(CONFIG_GROUP, MANAGED_TAG_KEY);
		return name == null || name.isEmpty() ? DEFAULT_TAG_NAME : name;
	}

	/**
	 * Adds confirmed bag deposits to the managed tab, creating it when missing.
	 * Existing memberships and the user's tab icon are preserved across trips.
	 *
	 * @return whether a tab was created
	 */
	public boolean addDepositedItems(Set<Integer> canonicalIds)
	{
		String savedTabs = configManager.getConfiguration(
			BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG);
		List<String> tabNames = new ArrayList<>(Text.fromCSV(savedTabs == null ? "" : savedTabs));
		String managedName = configManager.getConfiguration(CONFIG_GROUP, MANAGED_TAG_KEY);
		Plugin bankTags = getBankTagsPlugin();
		TagManager tagManager = bankTags.getInjector().getInstance(TagManager.class);
		if (managedName != null && !managedName.isEmpty() && tabNames.contains(managedName))
		{
			if (addMissingItems(tagManager, managedName, canonicalIds))
			{
				bankTags.getInjector().getInstance(BankSearch.class).layoutBank();
			}
			return false;
		}

		if (managedName == null || managedName.isEmpty())
		{
			managedName = DEFAULT_TAG_NAME;
			int suffix = 2;
			while (tabNames.contains(managedName) || !tagManager.getItemsForTag(managedName).isEmpty())
			{
				managedName = DEFAULT_TAG_NAME + " " + suffix++;
			}
			configManager.setConfiguration(CONFIG_GROUP, MANAGED_TAG_KEY, managedName);
		}

		// Deleting a tab can leave its old item tags behind. Clear only our own tag
		// before recreating it so this new bag never inherits a previous bag's loot.
		tagManager.removeTag(managedName);
		addMissingItems(tagManager, managedName, canonicalIds);

		configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP,
			BankTagsPlugin.TAG_ICON_PREFIX + managedName, ItemID.LOOTING_BAG);
		tabNames.add(managedName);
		configManager.setConfiguration(
			BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tabNames));

		// Use Bank Tags' own injector so its live sidebar sees this exact manager.
		TabManager tabManager = bankTags.getInjector().getInstance(TabManager.class);
		TagTab tab = tabManager.find(managedName);
		if (tab == null)
		{
			tab = new TagTab();
			tab.setTag(managedName);
			tabManager.add(tab);
		}
		tab.setIconItemId(ItemID.LOOTING_BAG);

		// Do not call TabManager.save(): its list can be empty while the bank is closed.
		// The configuration merge above preserves every existing tab in that case.
		bankTags.getInjector().getInstance(BankSearch.class).layoutBank();
		return true;
	}

	private boolean addMissingItems(TagManager tagManager, String tagName, Set<Integer> canonicalIds)
	{
		Set<Integer> taggedIds = new HashSet<>(tagManager.getItemsForTag(tagName));
		boolean changed = false;
		for (Integer itemId : canonicalIds)
		{
			if (itemId != null && itemId > 0 && taggedIds.add(itemId))
			{
				tagManager.addTag(itemId, tagName, false);
				changed = true;
			}
		}
		return changed;
	}

	private Plugin getBankTagsPlugin()
	{
		return pluginManager.getPlugins().stream()
			.filter(BankTagsPlugin.class::isInstance)
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("Bank Tags must be loaded"));
	}
}

package com.lootingbagtags;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("lootingbagtags")
public interface LootingBagTagsConfig extends Config
{
	@ConfigItem(
		keyName = "openAfterDeposit",
		name = "Open newly created tab",
		description = "Show the bag tag when first created. Later deposits add item types without switching tabs. Quantities are bank totals.",
		position = 0
	)
	default boolean openAfterDeposit()
	{
		return true;
	}
}

package com.lootingbagtags;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;

@Slf4j
@PluginDescriptor(
	name = "Looting Bag Tags",
	internalName = "looting-bag-tags",
	description = "Adds looting bag deposits to a dedicated bank tag tab",
	tags = {"bank", "looting", "bag", "tags", "deposits"}
)
@PluginDependency(BankTagsPlugin.class)
public class LootingBagTagsPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ItemManager itemManager;
	@Inject private ConfigManager configManager;
	@Inject private LootingBagTagsConfig config;
	@Inject private LootingBagTagWriter tagWriter;
	@Inject private BankTagsService bankTagsService;

	private final BagDepositTracker tracker = new BagDepositTracker();
	private boolean bankWasOpen;
	private boolean containersChanged;

	@Provides
	LootingBagTagsConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(LootingBagTagsConfig.class);
	}

	@Override
	protected void startUp()
	{
		reset();
		clientThread.invokeLater(() ->
		{
			configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, "useTabs", true);
		});
		log.info("Looting Bag Tags enabled");
	}

	@Override
	protected void shutDown()
	{
		reset();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING
			|| state == GameState.CONNECTION_LOST || state == GameState.LOGGING_IN)
		{
			reset();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.LOOTING_BAG
			|| event.getContainerId() == InventoryID.BANK)
		{
			containersChanged = true;
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		updateBankVisit();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		updateBankVisit();
		if (bankWasOpen && containersChanged)
		{
			reconcileDeposits();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		int component = event.getParam1();
		if (component != InterfaceID.Bankmain.DEPOSITCONTAINERS
			&& component != InterfaceID.Bankside.LOOTINGBAG_BANKALL
			&& component != InterfaceID.Bankside.LOOTINGBAG_ITEMS)
		{
			return;
		}
		updateBankVisit();
		if (bankWasOpen)
		{
			// Finish any preceding deposit before another click can reset its baseline.
			reconcileDeposits();
			tracker.prime(snapshot(InventoryID.LOOTING_BAG), snapshot(InventoryID.BANK), true);
		}
	}

	private void updateBankVisit()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS);
		boolean open = client.getGameState() == GameState.LOGGED_IN
			&& bank != null && !bank.isHidden();
		if (open == bankWasOpen)
		{
			return;
		}
		bankWasOpen = open;
		tracker.prime(snapshot(InventoryID.LOOTING_BAG), open ? snapshot(InventoryID.BANK) : null, open);
		containersChanged = false;
	}

	private void reconcileDeposits()
	{
		Set<Integer> deposited = tracker.detect(
			snapshot(InventoryID.LOOTING_BAG), snapshot(InventoryID.BANK), true);
		containersChanged = false;
		if (deposited.isEmpty())
		{
			return;
		}

		boolean created = tagWriter.addDepositedItems(deposited);
		if (created && config.openAfterDeposit())
		{
			bankTagsService.openBankTag(tagWriter.getTagName(), BankTagsService.OPTION_ALLOW_MODIFICATIONS);
		}
		log.debug("Observed {} looting bag item types; created tab: {}", deposited.size(), created);
	}

	private Map<Integer, Integer> snapshot(int containerId)
	{
		ItemContainer container = client.getItemContainer(containerId);
		if (container == null)
		{
			return null;
		}
		Map<Integer, Integer> items = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				int id = itemManager.canonicalize(item.getId());
				// Use saturation for large stacks instead of overflowing an integer.
				items.merge(id, item.getQuantity(), (left, right) ->
					(int) Math.min(Integer.MAX_VALUE, (long) left + right));
			}
		}
		return items;
	}

	private void reset()
	{
		tracker.reset();
		bankWasOpen = false;
		containersChanged = false;
	}
}

package com.lootingbagtags;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class BagDepositTrackerTest
{
	@Test
	public void reportsOnlyBagItemsThatActuallyArrivedInBank()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.prime(items(100, 37, 200, 2), items(100, 500, 300, 25), true);

		assertEquals(ids(100, 200), tracker.detect(items(), items(100, 537, 200, 2, 300, 30), true));
	}

	@Test
	public void ignoresOrdinaryInventoryDeposits()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.prime(items(100, 37), items(100, 500), true);

		assertTrue(tracker.detect(items(100, 37), items(100, 537, 200, 2), true).isEmpty());
	}

	@Test
	public void ignoresBagLossesWithoutMatchingBankGains()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.prime(items(100, 37, 200, 2), items(100, 500), true);

		assertEquals(ids(100), tracker.detect(items(), items(100, 537, 300, 2), true));
	}

	@Test
	public void handlesPartialBagDepositsAndDoesNotRepeatThem()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.prime(items(100, 37), items(100, 500), true);

		assertEquals(ids(100), tracker.detect(items(100, 27), items(100, 510), true));
		assertTrue(tracker.detect(items(100, 27), items(100, 510), true).isEmpty());
		assertEquals(ids(100), tracker.detect(items(), items(100, 537), true));
	}

	@Test
	public void acceptsOnlyTheMatchingPartOfABagLoss()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.prime(items(100, 37), items(100, 500), true);

		assertEquals(ids(100), tracker.detect(items(), items(100, 501), true));
	}

	@Test
	public void emptyBagContainerIsNotTheSameAsUnknownBagContainer()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.prime(items(100, 37), items(100, 500), true);

		assertTrue(tracker.detect(null, items(100, 537), true).isEmpty());
		assertTrue(tracker.detect(items(), items(100, 537), true).isEmpty());
	}

	@Test
	public void doesNotAttributeAChangeAcrossAnUnknownBankSnapshot()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.prime(items(100, 37), items(100, 500), true);

		assertTrue(tracker.detect(items(100, 37), null, true).isEmpty());
		assertTrue(tracker.detect(items(), items(100, 537), true).isEmpty());
	}

	@Test
	public void firstSnapshotNeverReportsHistoricalLoot()
	{
		BagDepositTracker tracker = new BagDepositTracker();

		assertTrue(tracker.detect(items(100, 37), items(100, 500), true).isEmpty());
		assertEquals(ids(100), tracker.detect(items(), items(100, 537), true));
	}

	@Test
	public void bagLossOutsideBankAndLaterInventoryDepositAreNotLootBagDeposits()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.detect(items(100, 37), null, false);
		assertTrue(tracker.detect(items(), null, false).isEmpty());
		assertTrue(tracker.detect(items(), items(100, 500), true).isEmpty());
		assertTrue(tracker.detect(items(), items(100, 537), true).isEmpty());
	}

	@Test
	public void eachBankVisitNeedsAFreshBeforeDepositSnapshot()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.prime(items(100, 37), items(100, 500), true);
		assertEquals(ids(100), tracker.detect(items(), items(100, 537), true));

		tracker.detect(items(200, 2), items(100, 537), false);
		assertTrue(tracker.detect(items(200, 2), items(100, 537), true).isEmpty());
		assertEquals(ids(200), tracker.detect(items(), items(100, 537, 200, 2), true));
	}

	@Test
	public void resetPreventsCrossAccountOrWorldHopMatches()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.prime(items(100, 37), items(100, 500), true);
		tracker.reset();

		assertTrue(tracker.detect(items(), items(100, 537), true).isEmpty());
	}

	@Test
	public void unmatchedChangesDoNotCarryForwardIntoUnrelatedLaterChanges()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.prime(items(100, 37), items(100, 500), true);

		assertTrue(tracker.detect(items(), items(100, 500), true).isEmpty());
		assertTrue(tracker.detect(items(), items(100, 537), true).isEmpty());
	}

	@Test
	public void copiesCallerOwnedMapsInsteadOfKeepingLiveViews()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		Map<Integer, Integer> bag = items(100, 37);
		Map<Integer, Integer> bank = items(100, 500);
		tracker.prime(bag, bank, true);

		bag.clear();
		bank.put(100, 537);
		assertEquals(ids(100), tracker.detect(bag, bank, true));
	}

	@Test
	public void ignoresEmptySlotsAndInvalidEntries()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		Map<Integer, Integer> bag = items(-1, 1, 100, 37, 200, 0, 300, -1);
		bag.put(null, 12);
		bag.put(400, null);
		tracker.prime(bag, items(100, 500), true);

		assertEquals(ids(100), tracker.detect(items(), items(100, 537), true));
	}

	@Test(expected = UnsupportedOperationException.class)
	public void returnedItemTypesCannotBeMutated()
	{
		BagDepositTracker tracker = new BagDepositTracker();
		tracker.prime(items(100, 37), items(), true);
		tracker.detect(items(), items(100, 37), true).add(200);
	}

	private static Map<Integer, Integer> items(int... pairs)
	{
		Map<Integer, Integer> items = new HashMap<>();
		for (int index = 0; index < pairs.length; index += 2)
		{
			items.put(pairs[index], pairs[index + 1]);
		}
		return items;
	}

	private static Set<Integer> ids(Integer... values)
	{
		return new HashSet<>(Arrays.asList(values));
	}
}

package com.lootingbagtags;

import com.google.inject.Injector;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.TabManager;
import net.runelite.client.plugins.banktags.tabs.TagTab;
import net.runelite.client.util.Text;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.stubbing.Answer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.verifyNoMoreInteractions;
import static org.mockito.Mockito.when;

public class LootingBagTagWriterTest
{
	private static final String TAG_NAME = "looting bag deposits";
	private static final String OWNED_NAME_KEY = "lootingbagtags.managedTag";
	private static final String TAB_NAMES_KEY = "banktags.tagtabs";

	private final Map<String, String> configuration = new HashMap<>();
	private final Map<Integer, Set<String>> itemTags = new HashMap<>();
	private final List<TagTab> liveTabs = new ArrayList<>();

	private ConfigManager configManager;
	private PluginManager pluginManager;
	private Injector injector;
	private TagManager tagManager;
	private TabManager tabManager;
	private BankSearch bankSearch;
	private LootingBagTagWriter writer;

	@Before
	public void setUp()
	{
		configManager = mock(ConfigManager.class);
		pluginManager = mock(PluginManager.class);
		injector = mock(Injector.class);
		tagManager = mock(TagManager.class);
		tabManager = mock(TabManager.class);
		bankSearch = mock(BankSearch.class);
		writer = new LootingBagTagWriter(configManager, pluginManager);

		when(configManager.getConfiguration(anyString(), anyString())).thenAnswer(invocation ->
			configuration.get(invocation.getArgument(0) + "." + invocation.getArgument(1)));
		Answer<Void> saveConfiguration = invocation ->
		{
			configuration.put(invocation.getArgument(0) + "." + invocation.getArgument(1),
				String.valueOf((Object) invocation.getArgument(2)));
			return null;
		};
		doAnswer(saveConfiguration).when(configManager).setConfiguration(anyString(), anyString(), anyString());
		doAnswer(saveConfiguration).when(configManager).setConfiguration(anyString(), anyString(), any(Object.class));

		when(pluginManager.getPlugins()).thenReturn(Collections.singletonList(new TestBankTagsPlugin(injector)));
		when(injector.getInstance(TagManager.class)).thenReturn(tagManager);
		when(injector.getInstance(TabManager.class)).thenReturn(tabManager);
		when(injector.getInstance(BankSearch.class)).thenReturn(bankSearch);

		when(tagManager.getItemsForTag(anyString())).thenAnswer(invocation ->
		{
			String tag = invocation.getArgument(0);
			return itemTags.entrySet().stream()
				.filter(entry -> entry.getValue().contains(tag))
				.map(Map.Entry::getKey)
				.collect(Collectors.toList());
		});
		doAnswer(invocation ->
		{
			String tag = invocation.getArgument(0);
			itemTags.values().forEach(tags -> tags.remove(tag));
			return null;
		}).when(tagManager).removeTag(anyString());
		doAnswer(invocation ->
		{
			Integer itemId = invocation.getArgument(0);
			String tag = invocation.getArgument(1);
			itemTags.computeIfAbsent(itemId, ignored -> new HashSet<>()).add(tag);
			return null;
		}).when(tagManager).addTag(anyInt(), anyString(), anyBoolean());

		when(tabManager.find(anyString())).thenAnswer(invocation ->
		{
			String name = invocation.getArgument(0);
			return liveTabs.stream().filter(tab -> tab.getTag().equals(name)).findFirst().orElse(null);
		});
		doAnswer(invocation ->
		{
			liveTabs.add(invocation.getArgument(0));
			return null;
		}).when(tabManager).add(any(TagTab.class));
	}

